CREATE OR REPLACE FUNCTION public.delivery_transition_job(p_job_id uuid, p_expected_status text, p_next_status text, p_request_key uuid, p_recipient text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role text := (
    select u.primary_role::text from public.users u
    where u.id = auth.uid() and u.is_active
  );
  v_job public.delivery_jobs%rowtype;
  v_booking public.bookings%rowtype;
  v_receipt public.delivery_job_events%rowtype;
  v_manager boolean;
  v_warehouse boolean;
  v_assigned_driver boolean;
begin
  if v_actor is null or p_job_id is null or p_request_key is null
     or not exists (select 1 from public.users u where u.id=v_actor and u.is_active) then
    raise exception 'Delivery transition requires an authenticated actor' using errcode='42501';
  end if;
  select * into v_job from public.delivery_jobs where id=p_job_id for update;
  if not found then raise exception 'Delivery job not found'; end if;
  v_manager := v_role in ('Owner','Admin') or (
    v_role in ('Manager','Coordinator') and exists (
      select 1 from public.users u where u.id=v_actor and u.branch_id=v_job.branch_id
    )
  );
  v_warehouse := v_role='Warehouse' and exists (
    select 1 from public.users u where u.id=v_actor and u.branch_id=v_job.branch_id
  );
  v_assigned_driver := v_role='Driver' and v_job.assigned_driver_id=v_actor;
  if not (v_manager or v_warehouse or v_assigned_driver) then
    raise exception 'Delivery transition role or assignment denied' using errcode='42501';
  end if;

  select * into v_receipt from public.delivery_job_events where request_key=p_request_key;
  if found then
    if v_receipt.job_id=p_job_id and v_receipt.actor_id=v_actor
       and v_receipt.event_kind='Transition'
       and v_receipt.previous_status=p_expected_status
       and v_receipt.next_status=p_next_status
       and v_receipt.metadata->>'request_fingerprint' = md5(
         jsonb_build_array(p_request_key::text, coalesce(btrim(p_recipient),''),
                           coalesce(btrim(p_note),''))::text
       ) then
      return p_job_id;
    end if;
    raise exception 'Transition key belongs to a different request';
  end if;

  if v_job.status is distinct from p_expected_status then
    raise exception 'Delivery status changed. Reload before saving.' using errcode='40001';
  end if;
  if not (
      (p_expected_status='Scheduled' and p_next_status='Ready' and (v_manager or v_warehouse))
   or (p_expected_status='Ready' and p_next_status='In Transit' and (v_manager or v_assigned_driver))
   or (p_expected_status='In Transit' and p_next_status='Delivered' and (v_manager or v_assigned_driver))
   or (p_expected_status in ('Scheduled','Ready','In Transit') and p_next_status='Failed' and v_manager)
  ) then raise exception 'This delivery transition is not permitted'; end if;

  select * into v_booking from public.bookings where id=v_job.booking_id for share;
  if not found or v_booking.cancelled_at is not null then
    raise exception 'Cancelled or missing booking cannot be dispatched'; end if;
  if p_next_status in ('Ready','In Transit') and v_job.leg='Outbound'
     and v_booking.stage not in ('Packed','On Rent') then
    raise exception 'Packing must finish before outbound dispatch';
  end if;
  if p_next_status='In Transit' and (
    v_job.assigned_driver_id is null or not exists (
      select 1 from public.users u
      where u.id=v_job.assigned_driver_id and u.primary_role='Driver'
        and u.is_active and u.branch_id=v_job.branch_id
    )
  ) then raise exception 'An active assigned driver is required before dispatch'; end if;
  if p_next_status='Delivered' and length(btrim(coalesce(p_recipient,'')))<2 then
    raise exception 'Delivery receipt requires the recipient name';
  end if;
  if p_next_status='Failed' and length(btrim(coalesce(p_note,'')))<10 then
    raise exception 'Failed dispatch requires an explanatory note';
  end if;

  update public.delivery_jobs
  set status=p_next_status,
      dispatched_at=case when p_next_status='In Transit' then now() else dispatched_at end,
      delivered_at=case when p_next_status='Delivered' then now() else delivered_at end,
      received_by=case when p_next_status='Delivered' then btrim(p_recipient) else received_by end,
      last_note=nullif(btrim(coalesce(p_note,'')),''),
      version=version+1, updated_at=now(),updated_by=v_actor
  where id=p_job_id;

  insert into public.delivery_job_events
    (request_key,job_id,event_kind,previous_status,next_status,actor_id,metadata)
  values (p_request_key,p_job_id,'Transition',p_expected_status,p_next_status,v_actor,
          jsonb_build_object('request_fingerprint',md5(
            jsonb_build_array(p_request_key::text, coalesce(btrim(p_recipient),''),
                              coalesce(btrim(p_note),''))::text
          )));
  return p_job_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_record_editor(p_kind text, p_id uuid, p_revision text, p_key uuid, p_values jsonb, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare tab text; child_tab text; fk text; allowed text[]; child_allowed text[]; identity uuid:=p_id; row_data jsonb; patch jsonb; child_id uuid; existing jsonb; response jsonb; request jsonb; saved record; kept uuid[]:='{}'; warehouse_branch uuid; generated_code text; current_snapshot jsonb; serial_count int:=0;
begin
  if auth.uid() is null or not coalesce(auth_user_role()::text=any(case when p_kind='client' then (case when p_id is null then array['Owner','Admin','Manager','Coordinator','Warehouse'] else array['Owner','Admin','Manager','Coordinator'] end) else array['Owner','Admin','Manager'] end),false) then raise exception 'Permission denied for this record.' using errcode='42501'; end if;
  if p_key is null then raise exception 'A save key is required.'; end if;
  if jsonb_typeof(p_values)<>'object' or jsonb_typeof(p_rows)<>'array' then raise exception 'Invalid record payload.'; end if;
  request:=jsonb_build_object('kind',p_kind,'id',p_id,'revision',p_revision,'values',p_values,'rows',p_rows);
  perform pg_advisory_xact_lock(hashtextextended(p_key::text,0));
  select * into saved from record_editor_private.receipts where key=p_key;
  if found then
    if saved.actor<>auth.uid() or saved.request<>request then raise exception 'This save key belongs to a different change.'; end if;
    return saved.response;
  end if;
  allowed:=record_editor_private.fields(p_kind);
  if allowed is null then raise exception 'Unknown record kind'; end if;
  tab:=case p_kind when 'client' then 'clients' when 'equipment' then 'products' else 'bundles' end;
  child_tab:=case p_kind when 'client' then 'client_contacts' when 'equipment' then 'product_units' else 'bundle_items' end;
  fk:=case p_kind when 'client' then 'client_id' when 'equipment' then 'product_id' else 'bundle_id' end;
  child_allowed:=case p_kind when 'client' then array['full_name','designation','phone','email'] when 'equipment' then array['asset_tag','serial_no','warehouse_id','rack','shelf','bin'] else array['product_id','quantity','days','is_mandatory','sort_order'] end;
  if p_id is null and p_kind='equipment' then allowed:=allowed||array['tracking_mode','total_quantity']; child_allowed:=child_allowed||array['condition']; end if;
  if exists(select 1 from jsonb_object_keys(p_values) k where not k=any(allowed)) then raise exception 'One of these fields cannot be edited here.'; end if;
  if p_id is not null then
    execute format('select to_jsonb(t) from public.%I t where id=$1 for update',tab) into existing using p_id;
    if existing is null then raise exception 'Record not found.'; end if;
    -- Child locks prevent an in-flight unit/component edit from passing the revision check.
    execute format('select 1 from public.%I where %I=$1 for update',child_tab,fk) using p_id;
    current_snapshot:=record_editor_private.read_snapshot(p_kind,p_id::text);
    if p_revision is null or p_revision<>current_snapshot->>'revision' then raise exception 'This record changed since you opened it. Reload the latest record before saving. Your changes have not been saved.' using errcode='40001'; end if;
  end if;
  patch:=p_values;
  if p_kind='client' then
    if patch ? 'country' and patch->>'country' is null then patch:=patch||'{"country":"Nepal"}'; end if;
    if patch ? 'type_parent' and patch->>'type_parent'<>'Organisation' then patch:=patch||'{"org_subtype":null}'; end if;
    if jsonb_array_length(p_rows)>1 then raise exception 'Only one primary contact is supported.'; end if;
  end if;
  if patch ? 'name' and nullif(btrim(patch->>'name'),'') is null then raise exception 'Name is required.'; end if;
  if p_kind='bundle' and jsonb_array_length(p_rows)=0 then raise exception 'Add at least one component.'; end if;
  if p_id is null then
    generated_code:=next_document_number(case p_kind when 'client' then 'client' when 'equipment' then 'equipment' else 'bundle' end);
    patch:=patch||jsonb_build_object('client_uuid',p_key,'created_by',auth.uid(),case p_kind when 'client' then 'client_code' when 'equipment' then 'asset_code' else 'bundle_code' end,generated_code);
    if p_kind='equipment' then
      if coalesce(patch->>'tracking_mode','Serialised')='Serialised' then
        if jsonb_array_length(p_rows)=0 then raise exception 'Add at least one unit.'; end if;
        patch:=patch||jsonb_build_object('total_quantity',jsonb_array_length(p_rows));
      end if;
      patch:=patch||'{"status":"Active"}';
    end if;
  else patch:=patch||jsonb_build_object('updated_at',clock_timestamp());
  end if;
  begin
    identity:=record_editor_private.write_row(tab,p_id,patch);
  exception when unique_violation then
    raise exception '%', case when p_kind='client' then 'A client with this phone number already exists. Open the existing client instead. Your changes have not been saved.' else 'A record with these details already exists. Your changes have not been saved.' end using errcode='23505';
  end;
  for row_data in select value from jsonb_array_elements(p_rows) loop
    child_id:=(row_data->>'id')::uuid;
    if exists(select 1 from jsonb_object_keys(row_data) k where not k=any(child_allowed||array['id','name','status','condition'])) then raise exception 'Unsupported component or unit field.'; end if;
    if child_id is not null then
      execute format('select to_jsonb(t) from public.%I t where id=$1 and %I=$2',child_tab,fk) into existing using child_id,identity;
      if existing is null then raise exception 'This row does not belong to the record.'; end if;
      if p_kind='bundle' and not (existing->>'is_active')::boolean then raise exception 'This component has been removed. Reload first.'; end if;
      if p_kind='equipment' and (row_data->>'condition' is distinct from existing->>'condition' or row_data->>'status' is distinct from existing->>'status') then raise exception 'Use the operational workflow to change condition or custody.'; end if;
    elsif p_id is not null and p_kind='equipment' then raise exception 'Use equipment intake to add units; stock cannot change through Edit.';
    end if;
    patch:=record_editor_private.pick(row_data,child_allowed);
    if p_kind='equipment' then
      if child_id is not null and existing->>'status' not in ('In Stock','Reserved') and (record_editor_private.pick(existing,array['warehouse_id','rack','shelf','bin'])<>record_editor_private.pick(row_data,array['warehouse_id','rack','shelf','bin'])) then raise exception 'Location changes require the equipment to be in stock or reserved.'; end if;
      select branch_id into warehouse_branch from warehouses where id=(patch->>'warehouse_id')::uuid;
      if warehouse_branch is null then raise exception 'Select a warehouse for every unit.'; end if;
      patch:=patch||jsonb_build_object('branch_id',warehouse_branch);
      if child_id is null then serial_count:=serial_count+1; patch:=patch||jsonb_build_object('asset_tag',generated_code||'-'||lpad(serial_count::text,2,'0')); end if;
    end if;
    if child_id is null then patch:=patch||jsonb_build_object(fk,identity,'client_uuid',gen_random_uuid(),'created_by',auth.uid());
      if p_kind='client' then patch:=patch||'{"is_primary":true}'; end if;
    end if;
    child_id:=record_editor_private.write_row(child_tab,child_id,patch);
    kept:=array_append(kept,child_id);
  end loop;
  if p_kind='equipment' and exists(select 1 from product_units where product_id=identity and not id=any(kept)) then raise exception 'Units cannot be removed here. Use the stock or retirement workflow.'; end if;
  if p_kind='client' then update client_contacts set status='Deactivated',is_primary=false,deactivated_at=now(),deactivated_by=auth.uid() where client_id=identity and is_primary and status='Active' and not id=any(kept); end if;
  if p_kind='bundle' then update bundle_items set is_active=false,deactivated_at=now(),deactivated_by=auth.uid() where bundle_id=identity and is_active and not id=any(kept); end if;
  response:=record_editor_private.read_snapshot(p_kind,identity::text);
  insert into audit_events(client_uuid,event_class,category,module,action,severity,status,table_name,record_id,actor_id,actor_role,new_values)
  values(p_key,'status change',(case when p_kind='client' then 'Administration' else 'Inventory' end)::audit_category,(case when p_kind='client' then 'Clients' else 'Inventory' end)::audit_module,'Update','Informational','Success',tab,identity,auth.uid(),auth_user_role(),jsonb_build_object('revision',response->>'revision'));
  insert into record_editor_private.receipts(key,actor,request,response) values(p_key,auth.uid(),request,response);
  return response;
end; $function$

CREATE OR REPLACE FUNCTION public.cancel_booking(p_booking_id uuid, p_reason text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return public.cancel_booking(jsonb_build_object(
    'booking_id', p_booking_id,
    'reason', p_reason
  ));
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_booking(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking_id    uuid := (p_payload ->> 'booking_id')::uuid;
  v_reason        text := btrim(coalesce(p_payload ->> 'reason', ''));
  v_actor         uuid;
  v_role          system_role;
  v_booking       bookings%rowtype;
  v_now           timestamptz := now();
  v_client_uuid   uuid := nullif(coalesce(p_payload ->> 'client_uuid', ''), '')::uuid;
begin
  if v_booking_id is null then
    raise exception 'cancel_booking: booking_id is required.';
  end if;

  if char_length(v_reason) < 10 then
    raise exception
      'cancel_booking: cancellation reason must be at least 10 characters (got % characters). State why the booking is being cancelled.',
      char_length(v_reason);
  end if;

  -- 1. Read booking
  select * into v_booking from bookings where id = v_booking_id;
  if not found then
    raise exception 'cancel_booking: booking % does not exist.', v_booking_id;
  end if;

  if v_booking.cancelled_at is not null then
    raise exception 'cancel_booking: booking % is already cancelled (at %).',
      v_booking.booking_no, v_booking.cancelled_at;
  end if;

  if v_booking.closed_at is not null or v_booking.stage = 'Closed' then
    raise exception 'cancel_booking: booking % is Closed and cannot be cancelled.', v_booking.booking_no;
  end if;

  if v_booking.stage in ('On Rent', 'Returned') then
    raise exception
      'cancel_booking: booking % is at stage % and cannot be cancelled. Gear in the field must be returned and settled.',
      v_booking.booking_no, v_booking.stage;
  end if;

  -- Check if any unit lines are picked up
  if exists (
    select 1 from booking_line_units blu
     join booking_lines bl on bl.id = blu.booking_line_id
     where bl.booking_id = v_booking_id
       and blu.unit_state = 'Picked Up'
  ) then
    raise exception 'cancel_booking: booking % has units already picked up and cannot be cancelled.', v_booking.booking_no;
  end if;

  -- 2. Role & permission validation (R-05, PERMISSIONS.md)
  v_role := auth_user_role();
  if v_role is null or v_role not in ('Owner', 'Admin', 'Manager', 'Coordinator') then
    raise exception
      'cancel_booking: this session (%) may not cancel a booking. Coordinator, Manager, Admin and Owner only.',
      coalesce(v_role::text, 'unidentified')
      using errcode = '42501';
  end if;

  if v_booking.stage = 'Packed' and v_role = 'Coordinator' then
    raise exception
      'cancel_booking: booking % is Packed. Cancelling a Packed booking requires Manager, Admin or Owner authority.',
      v_booking.booking_no
      using errcode = '42501';
  end if;

  -- 3. Resolve actor strictly from authenticated session (never forgeable by caller)
  v_actor := auth_user_id();
  if v_actor is null then
    raise exception 'cancel_booking: an authenticated user is required to cancel a booking.'
      using errcode = '42501';
  end if;

  -- 4. Update bookings row (SECURITY DEFINER bypasses reject_direct_booking_stage_write)
  update bookings
     set cancelled_at        = v_now,
         cancelled_by        = v_actor,
         cancellation_reason = v_reason,
         updated_at          = v_now
   where id = v_booking_id;

  -- 5. Record audit event
  if v_client_uuid is null then
    v_client_uuid := gen_random_uuid();
  end if;

  insert into audit_events (
    client_uuid,
    event_class,
    category,
    module,
    action,
    severity,
    status,
    table_name,
    record_id,
    actor_id,
    actor_role,
    branch_id,
    old_values,
    new_values,
    reason
  ) values (
    v_client_uuid,
    'status change',
    'Rentals',
    'Rentals',
    'Update',
    'Informational',
    'Success',
    'bookings',
    v_booking_id,
    v_actor,
    v_role,
    v_booking.branch_id,
    jsonb_build_object(
      'cancelled_at', null,
      'stage', v_booking.stage
    ),
    jsonb_build_object(
      'cancelled_at', v_now,
      'cancelled_by', v_actor,
      'cancellation_reason', v_reason,
      'stage', v_booking.stage
    ),
    v_reason
  );

  return jsonb_build_object(
    'success', true,
    'booking_id', v_booking_id,
    'booking_no', v_booking.booking_no,
    'cancelled_at', v_now,
    'cancelled_by', v_actor,
    'cancellation_reason', v_reason
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_rental_quote(p_id uuid, p_revision text, p_key uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare b bookings; req jsonb; receipt record; result jsonb; row_data jsonb; patch jsonb; existing jsonb; row_id uuid; kept uuid[]:='{}'; kept_crew uuid[]:='{}'; mapping jsonb:='{}'; parent_id uuid; transport_id uuid; audit_id uuid:=gen_random_uuid(); first_discount uuid; discount_pct numeric; rate numeric; base_rate numeric;
begin
  if auth.uid() is null or not coalesce(auth_user_role()::text in ('Owner','Admin','Manager','Coordinator'),false) then raise exception 'You cannot edit this booking.' using errcode='42501'; end if;
  if p_key is null or p_revision is null then raise exception 'Reload this booking before saving.'; end if;
  req:=jsonb_build_object('booking',p_id,'revision',p_revision,'payload',p_payload);
  perform pg_advisory_xact_lock(hashtextextended(p_key::text,0));
  select * into receipt from record_editor_private.receipts where key=p_key;
  if found then if receipt.actor<>auth.uid() or receipt.request<>req then raise exception 'This save key belongs to another change.'; end if; return receipt.response; end if;
  select * into b from bookings where id=p_id for update;
  if b.id is null then raise exception 'Booking not found.'; end if;
  if b.stage<>'Quote' or b.cancelled_at is not null then raise exception 'Only unconfirmed quotes can be edited.'; end if;
  perform 1 from booking_lines where booking_id=p_id for update;
  perform 1 from booking_crew_lines where booking_id=p_id for update;
  perform 1 from booking_transport where booking_id=p_id for update;
  perform 1 from booking_discounts where booking_id=p_id for update;
  perform 1 from invoices where booking_id=p_id for update;
  if exists(select 1 from invoices where booking_id=p_id and status::text not in ('Draft','Void')) then raise exception 'This booking has an issued financial document. Use the finance correction workflow.'; end if;
  if (read_quote_editor(p_id::text)->>'revision')<>p_revision then raise exception 'This booking changed since you opened it. Reload the latest record before saving.' using errcode='40001'; end if;
  if jsonb_typeof(p_payload->'lines')<>'array' or jsonb_typeof(p_payload->'crew')<>'array' then raise exception 'Invalid booking lines.'; end if;
  patch:=p_payload->'values';
  if exists(select 1 from jsonb_object_keys(patch) k where not k=any(array['client_id','project','project_type','project_type_other','pickup_at','return_at','delivery_type','pickup_location','return_location','deposit_required'])) then raise exception 'This booking field cannot be edited.'; end if;
  -- Client reassignment may not detach existing receipts from their account.
  if patch->>'client_id' is distinct from b.client_id::text and exists(select 1 from invoices where booking_id=p_id) then raise exception 'The client cannot change after a financial document has been created.'; end if;
  perform record_editor_private.write_row('bookings',p_id,patch||jsonb_build_object('updated_at',clock_timestamp(),'updated_by',auth.uid()));
  for row_data in select value from jsonb_array_elements(p_payload->'lines') loop
    row_id:=(row_data->>'id')::uuid;
    if row_id is not null then
      select to_jsonb(l) into existing from booking_lines l where id=row_id and booking_id=p_id and voided_at is null;
      if existing is null then raise exception 'A line no longer belongs to this quote. Reload before saving.'; end if;
      if row_data->>'client_uuid' is distinct from existing->>'client_uuid' then raise exception 'A line identity cannot change.'; end if;
    else existing:=null; end if;
    if row_data->>'client_uuid' is null then raise exception 'Every line needs a stable key.'; end if;
    patch:=record_editor_private.pick(row_data,array['line_type','product_id','bundle_id','description','qty','days','rate','discount_amount','is_included','service_basis','line_note','sort_order']);
    if row_data->>'parent_client_uuid' is not null or coalesce((patch->>'is_included')::boolean,false) then rate:=0; base_rate:=0;
    else
      base_rate:=get_model_daily_rate((patch->>'product_id')::uuid,(patch->>'bundle_id')::uuid);
      rate:=coalesce((patch->>'rate')::numeric,base_rate,0);
    end if;
    patch:=patch||jsonb_build_object('rate',rate,'rate_overridden',base_rate is not null and rate<>base_rate);
    if row_id is null then patch:=patch||jsonb_build_object('booking_id',p_id,'client_uuid',row_data->>'client_uuid','created_by',auth.uid()); end if;
    row_id:=record_editor_private.write_row('booking_lines',row_id,patch);
    if row_id=any(kept) then raise exception 'A booking line appears twice.'; end if;
    kept:=array_append(kept,row_id);mapping:=mapping||jsonb_build_object(row_data->>'client_uuid',row_id);
  end loop;
  for row_data in select value from jsonb_array_elements(p_payload->'lines') loop
    row_id:=(mapping->>(row_data->>'client_uuid'))::uuid;
    parent_id:=(mapping->>(row_data->>'parent_client_uuid'))::uuid;
    if row_data->>'parent_client_uuid' is not null and parent_id is null then raise exception 'The bundle parent is missing.'; end if;
    update booking_lines set parent_line_id=parent_id where id=row_id;
  end loop;
  update booking_lines set voided_at=now(),voided_reason='Removed while editing unconfirmed quote' where booking_id=p_id and voided_at is null and not id=any(kept);
  -- Assignments keep their identity and history. Over-allocation cannot survive a qty change.
  if exists(select 1 from booking_lines l where l.id=any(kept) and (select count(*) from booking_line_units u where u.booking_line_id=l.id and u.released_at is null)>l.qty) then raise exception 'Release assigned units before reducing this quantity.'; end if;
  for row_data in select value from jsonb_array_elements(p_payload->'crew') loop
    row_id:=(row_data->>'id')::uuid;
    if row_id is not null and not exists(select 1 from booking_crew_lines where id=row_id and booking_id=p_id and voided_at is null) then raise exception 'This crew row does not belong to the booking.'; end if;
    patch:=record_editor_private.pick(row_data,array['crew_member_id','name','crew_role','phone','day_rate','days','overtime','accommodation','meals']);
    if row_id is null then patch:=patch||jsonb_build_object('booking_id',p_id,'client_uuid',gen_random_uuid(),'created_by',auth.uid()); end if;
    row_id:=record_editor_private.write_row('booking_crew_lines',row_id,patch);kept_crew:=array_append(kept_crew,row_id);
  end loop;
  update booking_crew_lines set voided_at=now() where booking_id=p_id and voided_at is null and not id=any(kept_crew);
  select id into transport_id from booking_transport where booking_id=p_id;
  patch:=record_editor_private.pick(coalesce(p_payload->'transport','{}'),array['vehicle','number_plate','driver_contact','delivery_charge','fuel_charge','special_instructions']);
  if transport_id is not null or patch<>'{}' then
    if transport_id is null then patch:=patch||jsonb_build_object('booking_id',p_id,'client_uuid',gen_random_uuid(),'created_by',auth.uid()); end if;
    perform record_editor_private.write_row('booking_transport',transport_id,patch);
  end if;
  discount_pct:=(p_payload->>'discount_percent')::numeric;
  if discount_pct is null or discount_pct<0 or discount_pct>100 then raise exception 'Discount must be between 0 and 100 percent.'; end if;
  insert into audit_events(id,client_uuid,event_class,category,module,action,severity,status,table_name,record_id,actor_id,actor_role,branch_id,old_values,new_values)
  values(audit_id,p_key,'status change','Rentals','Rentals','Update','Informational','Success','bookings',p_id,auth.uid(),auth_user_role(),b.branch_id,jsonb_build_object('revision',p_revision),jsonb_build_object('edited','Quote'));
  if discount_pct is distinct from (select coalesce(sum(percent),0) from booking_discounts where booking_id=p_id) then
    select id into first_discount from booking_discounts where booking_id=p_id order by id limit 1;
    if first_discount is null and discount_pct>0 then
      insert into booking_discounts(client_uuid,booking_id,branch_id,discount_source,percent,reason,applied_by,audit_event_id) values(gen_random_uuid(),p_id,b.branch_id,'Manual',discount_pct,'Quote edited',auth.uid(),audit_id);
    else update booking_discounts set percent=case when id=first_discount then discount_pct else 0 end,reason='Quote edited',audit_event_id=audit_id where booking_id=p_id; end if;
  end if;
  -- Draft invoices retain their identity but must be refreshed by Finance before issue.
  -- Their existing line snapshots are never silently rewritten by a booking edit.
  if exists(select 1 from invoices where booking_id=p_id and status='Draft') then raise exception 'Void the draft invoice before editing this quote, then create its replacement from the updated booking.'; end if;
  result:=read_quote_editor(p_id::text);
  insert into record_editor_private.receipts(key,actor,request,response) values(p_key,auth.uid(),req,result);
  return result;
end; $function$

CREATE OR REPLACE FUNCTION public.extend_booking(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking_id    uuid := (p_payload ->> 'booking_id')::uuid;
  v_days          integer := coalesce((p_payload ->> 'days')::integer, (p_payload ->> 'extension_days')::integer, 0);
  v_reason        text := btrim(coalesce(p_payload ->> 'reason', ''));
  v_actor         uuid;
  v_role          system_role;
  v_booking       bookings%rowtype;
  v_now           timestamptz := now();
  v_old_return    timestamptz;
  v_new_return    timestamptz;
  v_client_uuid   uuid := nullif(coalesce(p_payload ->> 'client_uuid', ''), '')::uuid;
begin
  if v_booking_id is null then
    raise exception 'extend_booking: booking_id is required.';
  end if;

  if v_days < 1 then
    raise exception 'extend_booking: extension days must be at least 1 (got %).', v_days;
  end if;

  if char_length(v_reason) < 10 then
    raise exception
      'extend_booking: extension reason must be at least 10 characters (got % characters). State why the booking is being extended.',
      char_length(v_reason);
  end if;

  -- 1. Read booking
  select * into v_booking from bookings where id = v_booking_id;
  if not found then
    raise exception 'extend_booking: booking % does not exist.', v_booking_id;
  end if;

  if v_booking.cancelled_at is not null then
    raise exception 'extend_booking: booking % is cancelled and cannot be extended.', v_booking.booking_no;
  end if;

  if v_booking.closed_at is not null or v_booking.stage = 'Closed' then
    raise exception 'extend_booking: booking % is Closed and cannot be extended.', v_booking.booking_no;
  end if;

  if v_booking.stage = 'Returned' then
    raise exception 'extend_booking: booking % has already Returned and cannot be extended.', v_booking.booking_no;
  end if;

  if v_booking.stage not in ('Quote', 'Booked', 'Packed', 'On Rent') then
    raise exception 'extend_booking: booking % is at stage % and cannot be extended.', v_booking.booking_no, v_booking.stage;
  end if;

  -- 2. Role & permission validation (C+: Coordinator, Manager, Admin, Owner)
  v_role := auth_user_role();
  if v_role is null or v_role not in ('Owner', 'Admin', 'Manager', 'Coordinator') then
    raise exception
      'extend_booking: this session (%) may not extend a booking. Coordinator, Manager, Admin and Owner only.',
      coalesce(v_role::text, 'unidentified')
      using errcode = '42501';
  end if;

  -- 3. Resolve actor strictly from authenticated session
  v_actor := auth_user_id();
  if v_actor is null then
    raise exception 'extend_booking: an authenticated user is required to extend a booking.'
      using errcode = '42501';
  end if;

  -- 4. Calculate new return timestamp
  v_old_return := v_booking.return_at;
  v_new_return := v_old_return + (v_days || ' days')::interval;

  -- 5. Update bookings.return_at (triggers reservations_follow_booking_dates)
  update bookings
     set return_at = v_new_return,
         updated_at = v_now
   where id = v_booking_id;

  -- 6. Update booking_lines days
  update booking_lines
     set days = days + v_days,
         updated_at = v_now
   where booking_id = v_booking_id
     and voided_at is null
     and days is not null;

  -- 7. Update inventory_reservations (GiST exclusion and capacity ceiling re-evaluate here)
  -- D5 repair: inventory_reservations has NO updated_at column
  update inventory_reservations
     set period = tstzrange(lower(period), v_new_return, '[)')
   where booking_id = v_booking_id
     and released_at is null;

  -- 8. If a Draft invoice exists, increment invoice_lines.days (recalculate_invoice_totals trigger reprices it)
  update invoice_lines
     set days = days + v_days
   where invoice_id in (select id from invoices where booking_id = v_booking_id and status = 'Draft');

  -- 9. Insert audit log
  insert into audit_events (
    client_uuid,
    event_class,
    module,
    category,
    action,
    severity,
    status,
    table_name,
    record_id,
    actor_id,
    actor_role,
    branch_id,
    old_values,
    new_values,
    reason
  ) values (
    coalesce(v_client_uuid, gen_random_uuid()),
    'status change',
    'Rentals',
    'Rentals',
    'Update',
    'Informational',
    'Success',
    'bookings',
    v_booking_id,
    v_actor,
    v_role,
    v_booking.branch_id,
    jsonb_build_object(
      'return_at', v_old_return
    ),
    jsonb_build_object(
      'return_at', v_new_return,
      'days_added', v_days,
      'reason', v_reason
    ),
    v_reason
  );

  return jsonb_build_object(
    'success', true,
    'booking_id', v_booking_id,
    'booking_no', v_booking.booking_no,
    'old_return_at', v_old_return,
    'new_return_at', v_new_return,
    'days_added', v_days
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_invoice(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_invoice_id   uuid    := (p_payload ->> 'invoice_id')::uuid;
  v_actor        uuid    := nullif(coalesce(p_payload ->> 'issued_by', p_payload ->> 'actor_id', ''), '')::uuid;
  v_issue_date   date    := nullif(coalesce(p_payload ->> 'issue_date', ''), '')::date;
  v_role         system_role;
  v_invoice      invoices%rowtype;
  v_line_count   integer := 0;
  v_invoice_no   text;
  v_terms        text;
  v_term_days    integer := 0;
  v_due_date     date;
  v_new_status   invoice_status;
begin
  -- 1. Role & authorization checks (R-05)
  v_role := auth_user_role();
  if v_role is null or v_role not in ('Owner', 'Admin', 'Manager', 'Accounts') then
    raise exception
      'issue_invoice: this session (%) may not issue an invoice. R-05 gives that to Owner, Admin, Manager and Accounts.',
      coalesce(v_role::text, 'unidentified')
      using errcode = '42501';
  end if;

  if not auth_can_view_money() then
    raise exception
      'issue_invoice: this session cannot read money (Law 6), so it cannot issue an invoice.'
      using errcode = '42501';
  end if;

  if v_invoice_id is null then
    raise exception 'issue_invoice: invoice_id is required.';
  end if;

  -- 2. Verify invoice existence and eligibility
  select * into v_invoice from invoices where id = v_invoice_id;
  if not found then
    raise exception 'issue_invoice: invoice % does not exist.', v_invoice_id;
  end if;

  if v_invoice.voided_at is not null or v_invoice.status = 'Void' then
    raise exception 'issue_invoice: invoice % is voided and cannot be issued.', v_invoice_id;
  end if;

  if v_invoice.status <> 'Draft' or v_invoice.invoice_no is not null then
    raise exception
      'issue_invoice: invoice % is already issued (status %, invoice_no %). Only a Draft can be issued.',
      v_invoice_id, v_invoice.status, v_invoice.invoice_no;
  end if;

  select count(*) into v_line_count from invoice_lines where invoice_id = v_invoice_id;
  if v_line_count = 0 then
    raise exception 'issue_invoice: invoice % has no lines. An empty invoice cannot be issued.', v_invoice_id;
  end if;

  -- 3. Mint invoice number (R-15)
  v_invoice_no := next_document_number('invoice');
  if v_invoice_no is null then
    raise exception 'issue_invoice: next_document_number failed to mint an invoice number.';
  end if;

  -- 4. Date calculation
  v_issue_date := coalesce(v_issue_date, current_date);

  select payment_terms::text into v_terms from clients where id = v_invoice.client_id;
  v_term_days := case coalesce(v_terms, 'Immediate')
                   when '7 days'  then 7
                   when '15 days' then 15
                   when '30 days' then 30
                   else 0
                 end;
  v_due_date := v_issue_date + v_term_days;

  -- 5. Determine status
  if v_invoice.outstanding_amount = 0 and v_invoice.total_amount > 0 then
    v_new_status := 'Paid'::invoice_status;
  elsif v_invoice.paid_amount > 0 then
    v_new_status := 'Partially Paid'::invoice_status;
  else
    v_new_status := 'Sent'::invoice_status;
  end if;

  -- 6. Update the invoice row
  update invoices
     set invoice_no = v_invoice_no,
         issue_date = v_issue_date,
         due_date   = coalesce(v_due_date, due_date),
         status     = v_new_status,
         updated_at = now(),
         updated_by = coalesce(v_actor, v_invoice.updated_by)
   where id = v_invoice_id;

  -- 7. Read back updated invoice
  select * into v_invoice from invoices where id = v_invoice_id;

  return jsonb_build_object(
    'invoice_id',         v_invoice.id,
    'invoice_no',         v_invoice.invoice_no,
    'status',             v_invoice.status,
    'issue_date',         v_invoice.issue_date,
    'due_date',           v_invoice.due_date,
    'booking_id',         v_invoice.booking_id,
    'client_id',          v_invoice.client_id,
    'line_count',         v_line_count,
    'subtotal',           v_invoice.subtotal,
    'discount_amount',    v_invoice.discount_amount,
    'taxable_amount',     v_invoice.taxable_amount,
    'vat_amount',         v_invoice.vat_amount,
    'total_amount',       v_invoice.total_amount,
    'paid_amount',        v_invoice.paid_amount,
    'outstanding_amount', v_invoice.outstanding_amount
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.log_operation_session_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
begin
  begin
    v_actor := auth_user_id();
  exception when others then
    v_actor := null;
  end;
  if v_actor is null then
    begin
      v_actor := nullif(current_setting('app.current_user_id', true), '')::uuid;
    exception when others then
      v_actor := null;
    end;
  end if;
  v_actor := coalesce(v_actor, NEW.completed_by, NEW.started_by, NEW.created_by);

  insert into audit_events (
    client_uuid, event_class, category, module, action, severity, status,
    table_name, record_id, actor_id, old_values, new_values
  ) values (
    gen_random_uuid(), 'session', 'Rentals', 'Operations',
    case when TG_OP = 'INSERT' then 'Create'::audit_action else 'Update'::audit_action end,
    'Informational', 'Success',
    TG_TABLE_NAME, NEW.id, v_actor,
    case when TG_OP = 'UPDATE' then to_jsonb(OLD) else null end,
    to_jsonb(NEW)
  );
  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.log_audit_event_actor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_row jsonb := to_jsonb(NEW);
  v_module audit_module;
  v_category audit_category;
  v_class audit_event_class;
begin
  begin
    v_actor := auth_user_id();
  exception when others then
    v_actor := null;
  end;
  if v_actor is null then
    begin
      v_actor := nullif(current_setting('app.current_user_id', true), '')::uuid;
    exception when others then
      v_actor := null;
    end;
  end if;
  v_actor := coalesce(
    v_actor,
    nullif(v_row ->> 'updated_by', '')::uuid,
    nullif(v_row ->> 'created_by', '')::uuid
  );

  if TG_TABLE_NAME = 'cleaning_queue_entries' then
    v_module := 'Operations'; v_category := 'Rentals'; v_class := 'session';
  else
    v_module := 'Inventory'; v_category := 'Inventory'; v_class := 'status change';
  end if;

  insert into audit_events (
    client_uuid, event_class, category, module, action, severity, status,
    table_name, record_id, actor_id, old_values, new_values
  ) values (
    gen_random_uuid(), v_class, v_category, v_module,
    case when TG_OP = 'INSERT' then 'Create'::audit_action else 'Update'::audit_action end,
    'Informational', 'Success',
    TG_TABLE_NAME, NEW.id, v_actor,
    case when TG_OP = 'UPDATE' then to_jsonb(OLD) else null end,
    v_row
  );
  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_model_daily_rate(p_product_id uuid, p_bundle_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
